SELECT JSON_OBJECT('id',id,'version',game_version,'mode',mode,'status',status,'winner',winner,'score',JSON_EXTRACT(payload,'$.score'),'trust',JSON_UNQUOTE(JSON_EXTRACT(payload,'$.trust')),'transport',JSON_UNQUOTE(JSON_EXTRACT(payload,'$.transport')),'players',JSON_EXTRACT(payload,'$.players'),'participantKinds',JSON_EXTRACT(payload,'$.participantKinds'),'reported',JSON_ARRAY(JSON_TYPE(JSON_EXTRACT(payload,'$.submissions[0]'))<>'NULL',JSON_TYPE(JSON_EXTRACT(payload,'$.submissions[1]'))<>'NULL'),'reports',JSON_EXTRACT(payload,'$.submissions'),'startedAt',started_at,'endedAt',ended_at,'sha256',SHA2(CAST(payload AS CHAR),256)) FROM duel_matches WHERE id IN ('10423afe6e62a71ca7fa447336ab2733c5d20d471ab2adc20a1d7cb2321787e4','33c258b3f445129d4c99321b91cda15d8607d381d8e614f6a0e185d42d5dfbd3','a171d185fd65593b3b5ead45bee747158f8d2c2a23d73208c4fa71039f5dbbe3','28de3e8a6ab801a009e574193bedcb1270b29b702b3f4a75eadcbd9d68b49bbb','476c1e2e076a6c9d5989f4b8a61e74a23cdac6486c17a91a2bc22546d9274746','accb3a29ebd2f153a5e4b81e2350ce7a70f472523a3277e7ff4e8e695293990b') ORDER BY id;
